        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 5000000,
                    communityTrust: 20,
                    environmentalScore: 30,
                    legalRisk: 80,
                    reputation: 40,
                    trustHistory: [],
                    envHistory: [],
                    legalHistory: [],
                    repHistory: [],
                    cashHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    decision1: 'standard',
                    decision2: 'field',
                    decision3: 'comm_5'
                };
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };

            var titleEl = document.getElementById('briefingTitle');
            if (titleEl) titleEl.innerHTML = t(round.titleKey);

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = t(round.briefingKey);

            var badgeEl = document.getElementById('roundBadge');
            if (badgeEl) badgeEl.innerHTML = t('phase_label') + ' ' + (idx + 1);

            for (var di = 0; di < round.decisions.length; di++) {
                var dec = round.decisions[di];
                var gNum = dec.group;
                var label = document.getElementById('decision' + gNum + 'Label');
                var select = document.getElementById('decision' + gNum + 'Input');
                var hint = document.getElementById('decision' + gNum + 'Hint');
                if (label) label.textContent = t(dec.labelKey);
                if (hint) hint.textContent = t(dec.hintKey);
                if (select) {
                    select.innerHTML = '';
                    for (var oi = 0; oi < dec.options.length; oi++) {
                        var opt = document.createElement('option');
                        opt.value = dec.options[oi].value;
                        opt.textContent = t(dec.options[oi].textKey);
                        select.appendChild(opt);
                    }
                }
            }

            var group3 = document.getElementById('decisionGroup3');
            if (group3) {
                group3.style.display = round.showDecision3 ? 'block' : 'none';
            }
        }

        validateDecisions(decisions) {
            var d1 = document.getElementById('decision1Input');
            if (d1) decisions.decision1 = d1.value;

            var d2 = document.getElementById('decision2Input');
            if (d2) decisions.decision2 = d2.value;

            var d3 = document.getElementById('decision3Input');
            if (d3 && d3.offsetParent !== null) decisions.decision3 = d3.value;

            if (!decisions.decision1) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('validation_warning'), 'warning'
                );
                return false;
            }
            if (!decisions.decision2) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('validation_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        _findOption(roundIdx, group, value) {
            var round = this.ROUNDS[roundIdx];
            for (var di = 0; di < round.decisions.length; di++) {
                if (round.decisions[di].group === group) {
                    for (var oi = 0; oi < round.decisions[di].options.length; oi++) {
                        if (round.decisions[di].options[oi].value === value) {
                            return round.decisions[di].options[oi];
                        }
                    }
                }
            }
            return { cost: 0, envGain: 0, trustGain: 0, legalReduce: 0, repGain: 0 };
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var roundIdx = Math.min(state.currentPeriod - 1, this.ROUNDS.length - 1);

            var opt1 = this._findOption(roundIdx, 1, d.decision1);
            var opt2 = this._findOption(roundIdx, 2, d.decision2);
            var opt3 = { cost: 0, envGain: 0, trustGain: 0, legalReduce: 0, repGain: 0 };
            if (this.ROUNDS[roundIdx].showDecision3 && d.decision3) {
                opt3 = this._findOption(roundIdx, 3, d.decision3);
            }

            var totalCost = opt1.cost + opt2.cost + opt3.cost;
            var totalEnvGain = opt1.envGain + opt2.envGain + opt3.envGain;
            var totalTrustGain = opt1.trustGain + opt2.trustGain + opt3.trustGain;
            var totalLegalReduce = opt1.legalReduce + opt2.legalReduce + opt3.legalReduce;
            var totalRepGain = opt1.repGain + opt2.repGain + opt3.repGain;

            var randomFactor = 0.85 + Math.random() * 0.3;
            totalTrustGain = Math.round(totalTrustGain * randomFactor);
            totalEnvGain = Math.round(totalEnvGain * randomFactor);

            ds.cash -= totalCost;
            ds.communityTrust = Math.min(100, Math.max(0, ds.communityTrust + totalTrustGain));
            ds.environmentalScore = Math.min(100, Math.max(0, ds.environmentalScore + totalEnvGain));
            ds.legalRisk = Math.min(100, Math.max(0, ds.legalRisk - totalLegalReduce));
            ds.reputation = Math.min(100, Math.max(0, ds.reputation + totalRepGain));

            ds.cashHistory.push(ds.cash);
            ds.trustHistory.push(ds.communityTrust);
            ds.envHistory.push(ds.environmentalScore);
            ds.legalHistory.push(ds.legalRisk);
            ds.repHistory.push(ds.reputation);

            // Platform score 0 to 100: the getPerformanceSummary composite, mean of trust, environment, 100 minus legal risk and reputation, on the current values
            // legal risk is read as the summary reads it: a real 0 counts as 0, only a missing value counts as 100
            var legalForScore = (typeof ds.legalRisk === 'number') ? ds.legalRisk : 100;
            var runningComposite = Math.round(((ds.communityTrust || 0) + (ds.environmentalScore || 0) + (100 - legalForScore) + (ds.reputation || 0)) / 4);
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: Math.max(0, Math.min(100, runningComposite)) });

            var self = this;
            var maxP = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.maxPeriods) || this.ROUNDS.length;
            if (state.currentPeriod < maxP) {
                setTimeout(((__eqilNext) => function() {
                    self._updateBriefing({ currentPeriod: __eqilNext });
                })(state.currentPeriod + 1), 500);
            }

            return {
                period: state.currentPeriod,
                roundCost: totalCost,
                trustChange: totalTrustGain,
                envChange: totalEnvGain,
                legalChange: -totalLegalReduce,
                repChange: totalRepGain,
                cash: ds.cash,
                communityTrust: ds.communityTrust,
                environmentalScore: ds.environmentalScore,
                legalRisk: ds.legalRisk,
                reputation: ds.reputation
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash',
                (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('trustDisplay', 'domainState.communityTrust',
                (v) => Math.round(v) + '%');
            uiManager.bind('envDisplay', 'domainState.environmentalScore',
                (v) => Math.round(v) + '%');
            uiManager.bind('legalDisplay', 'domainState.legalRisk',
                (v) => Math.round(v) + '%');
            uiManager.bind('repDisplay', 'domainState.reputation',
                (v) => Math.round(v) + '%');

            // repaint the round content once the period has advanced or been undone
            var fw = window.mySimulation;
            if (!this._roundHooked && fw && fw.eventBus && typeof fw.eventBus.on === 'function') {
                this._roundHooked = true;
                var self = this;
                var repaint = function() {
                    var st = window.mySimulation && window.mySimulation.state;
                    if (st && (st.currentPeriod || 1) <= self.ROUNDS.length) self._updateBriefing(st);
                };
                fw.eventBus.on('period:submitted', repaint);
                fw.eventBus.on('period:undone', repaint);
            }
        }

