        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};
            var trust = r.communityTrust || 0;
            var env = r.environmentalScore || 0;
            var legal = (typeof r.legalRisk === 'number') ? r.legalRisk : 100;
            var rep = r.reputation || 0;
            var cash = r.cash || 0;

            var _t = function(k) {
                return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(k) : k;
            };

            var composite = (trust + env + (100 - legal) + rep) / 4;
            // `performance` stays the canonical English enum (likely grading key);
            // `performanceLabel` is the localized display value.
            var performance = 'Needs Improvement', perfKey = 'perf_needs';
            if (composite >= 50) { performance = 'Adequate'; perfKey = 'perf_adequate'; }
            if (composite >= 65) { performance = 'Good'; perfKey = 'perf_good'; }
            if (composite >= 80) { performance = 'Excellent'; perfKey = 'perf_excellent'; }

            var insights = [];
            if (trust >= 70) insights.push(_t('insight_trust_high'));
            if (trust < 40) insights.push(_t('insight_trust_low'));
            if (env >= 70) insights.push(_t('insight_env_high'));
            if (env < 40) insights.push(_t('insight_env_low'));
            if (legal <= 30) insights.push(_t('insight_legal_low'));
            if (legal > 50) insights.push(_t('insight_legal_high'));
            if (rep >= 70) insights.push(_t('insight_rep_high'));
            if (cash < 1000000) insights.push(_t('insight_cash_low'));

            return {
                compositeScore: Math.round(composite),
                communityTrust: trust,
                environmentalScore: env,
                legalRisk: legal,
                reputation: rep,
                remainingBudget: cash,
                performance: performance,
                performanceLabel: _t(perfKey),
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.legalRisk > 60 && state.currentPeriod > 1) {
                return window.mySimulation.t('hint_legal_high');
            }
            if (results.communityTrust < 30) {
                return window.mySimulation.t('hint_trust_low');
            }
            if (results.environmentalScore < 35) {
                return window.mySimulation.t('hint_env_low');
            }
            if (state.domainState.cash < 1000000) {
                return window.mySimulation.t('hint_budget_low');
            }
            if (results.communityTrust > 60 && results.environmentalScore > 60) {
                return window.mySimulation.t('hint_good_progress');
            }
            return null;
        }

